<?php
$layout = kimpu_homepage_section_value( 'hero', 'layout', 'split' ); $background = sanitize_hex_color( get_theme_mod( 'kimpu_hero_background_color', '#f4f8f7' ) ); $heading_color = sanitize_hex_color( get_theme_mod( 'kimpu_hero_heading_color', '#17283b' ) ); $image_id = absint( get_theme_mod( 'kimpu_hero_featured_image', 0 ) ); $bg_id = absint( get_theme_mod( 'kimpu_hero_background_image', 0 ) ); $bg_url = $bg_id ? wp_get_attachment_image_url( $bg_id, 'full' ) : ''; $style = '--hero-background:' . esc_attr( $background ? $background : '#f4f8f7' ) . ';--hero-heading:' . esc_attr( $heading_color ? $heading_color : '#17283b' ) . ';--hero-overlay:' . ( absint( get_theme_mod( 'kimpu_hero_overlay_opacity', 45 ) ) / 100 ) . ';--hero-spacing:' . absint( get_theme_mod( 'kimpu_hero_vertical_spacing', 88 ) ) . 'px;'; if ( $bg_url ) { $style .= 'background-image:url(' . esc_url( $bg_url ) . ');'; }
?>
<section class="homepage-hero homepage-hero-<?php echo esc_attr( $layout ); ?>" style="<?php echo esc_attr( $style ); ?>" id="hero">
    <div class="container homepage-hero-inner">
        <div class="homepage-hero-copy">
            <?php $eyebrow = get_theme_mod( 'kimpu_hero_eyebrow', __( 'WELCOME TO YOUR NEXT CHAPTER', 'kimpu-multipurpose' ) ); if ( $eyebrow ) : ?><p class="eyebrow"><?php echo esc_html( $eyebrow ); ?></p><?php endif; ?>
            <h1><?php echo esc_html( get_theme_mod( 'kimpu_hero_title', __( 'Build a better digital presence.', 'kimpu-multipurpose' ) ) ); ?></h1>
            <p class="hero-description"><?php echo esc_html( get_theme_mod( 'kimpu_hero_text', __( 'A clean, flexible WordPress foundation designed to grow with your ideas.', 'kimpu-multipurpose' ) ) ); ?></p>
            <div class="hero-actions"><?php $primary_text = get_theme_mod( 'kimpu_hero_primary_text', __( 'Explore articles', 'kimpu-multipurpose' ) ); $primary_url = get_theme_mod( 'kimpu_hero_primary_url', '#latest' ); if ( $primary_text && $primary_url ) : ?><a class="button" href="<?php echo esc_url( $primary_url ); ?>"><?php echo esc_html( $primary_text ); ?></a><?php endif; ?><?php $secondary_text = get_theme_mod( 'kimpu_hero_secondary_text', __( 'Learn more', 'kimpu-multipurpose' ) ); $secondary_url = get_theme_mod( 'kimpu_hero_secondary_url', '#about-theme' ); if ( $secondary_text && $secondary_url ) : ?><a class="button button-outline" href="<?php echo esc_url( $secondary_url ); ?>"><?php echo esc_html( $secondary_text ); ?></a><?php endif; ?></div>
        </div>
        <?php if ( 'centered' !== $layout ) : ?><div class="homepage-hero-media"><?php if ( $image_id ) { echo wp_get_attachment_image( $image_id, 'large', false, array( 'alt' => esc_attr( get_theme_mod( 'kimpu_hero_image_alt', '' ) ) ) ); } else { ?><div class="hero-visual" aria-hidden="true"><div class="visual-note"><span class="visual-dot"></span><span><?php esc_html_e( 'Flexible design', 'kimpu-multipurpose' ); ?></span></div><div class="visual-art"><div class="art-circle"></div><div class="art-card one"></div><div class="art-card two"></div><div class="art-card three"></div></div><div class="visual-bottom"><?php esc_html_e( 'Create. Customize. Grow.', 'kimpu-multipurpose' ); ?></div></div><?php } ?></div><?php endif; ?>
    </div>
</section>
